function partitionAssignment(numPartitions, machines) {
  const a = new Map(machines.map(m => [m, []]));
  for (let p = 0; p < numPartitions; p++) a.get(machines[p % machines.length]).push(p);
  return a;
}

function addMachine(assignment, newMachine) {
  const total = [...assignment.values()].reduce((s, ps) => s + ps.length, 0);
  const target = Math.floor(total / (assignment.size + 1));
  const taken = [];
  // steal from the most loaded machines until the newcomer has its share
  while (taken.length < target) {
    const [, ps] = [...assignment].sort((x, y) => y[1].length - x[1].length)[0];
    taken.push(ps.pop());
  }
  assignment.set(newMachine, taken);
  return assignment;
}

const a = partitionAssignment(1024, ['m1', 'm2', 'm3', 'm4']); // 256 each
addMachine(a, 'm5'); // m5 gets 204, others keep ~205 each; only 204 partitions moved
